import json
P='Tempora/Quad6-6r:Prelude#'
S='_`'
conv=' Lines are aligned 1:1 with the Latin row: an empty line stands where Kniewald has nothing (rubric, or a versicle he does not print), "_`" separators are copied.'
rows=[]
def add(k,lines,ref,note,checked='image'):
    rows.append({"id":P+k,"hr":"\n".join(lines),"ref":ref,"checked":checked,"note":note+conv})

